import {createRush,submitRushAnswer,skipRush,expireRush,advanceRush,endRush,rushRemaining,rushSummary} from './rush-logic.js?v=10';

const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clock=seconds=>{const s=Math.max(0,Math.ceil(Number(seconds)||0));return Math.floor(s/60)+':'+String(s%60).padStart(2,'0');};
const elapsed=milliseconds=>clock(Math.max(0,Number(milliseconds)||0)/1000);
const active=round=>round&&['active','feedback'].includes(round.status);
const label=section=>section==='Math'?'Math':'Reading and Writing';
const stars=n=>`<span class="rush-stars" aria-label="${n} speed star${n===1?'':'s'}">${'★'.repeat(Math.max(0,Math.min(3,n||0)))}${'☆'.repeat(3-Math.max(0,Math.min(3,n||0)))}</span>`;
const source=q=>`<details class="rush-source"><summary>Question source</summary><dl><dt>File</dt><dd>${esc(q.file)}</dd><dt>Page</dt><dd>${esc(q.page)}</dd><dt>Question</dt><dd>${esc(q.number)}</dd><dt>ID</dt><dd>${esc(q.id)}</dd></dl></details>`;
const localAsset=value=>{const path=value.split('#')[0];return /^assets\//.test(path)&&!/[%\\\x00-\x1f]/.test(path)&&path.split('/').every(part=>part&&part!=='.'&&part!=='..')&&/\.(pdf|png|jpe?g|webp|gif)$/i.test(path)&&(!value.includes('#')||/#page=\d+$/.test(value));};
const safeURL=value=>{try{const text=String(value||'');if(text.startsWith('apple-sat-library:'))return localAsset(decodeURIComponent(text.slice('apple-sat-library:'.length)))?esc(text):'';if(localAsset(text.replace(/^\.\//,'')))return esc(text);const url=new URL(text,typeof location==='undefined'?'https://local.invalid/':location.href);return ['http:','https:','asset:'].includes(url.protocol)?esc(text):'';}catch{return '';}};
const isTimedOut=result=>result?.timedOut===true||result?.timeout===true;
const outcome=result=>result?.correct?'Correct':isTimedOut(result)?'Time ran out':result?.skipped?'Skipped':'Incorrect';

export function createRushUI(context){
 const {getState,getData,save=()=>{},render:rerender=()=>{},grade,taken=()=>new Set(),canHard=()=>false,canTimed=()=>false,questionHTML,renderTools}=context;
 let filters={skill:'all',difficulty:'mixed',count:5,pace:'relaxed'},focused=false,selectedId=null,setupSection=null,previousSection=null,error='';
 const state=()=>getState();
 const studio=()=>{const s=state().studio ||= {};s.rushRounds ||= [];return s;};
 const questions=()=>getData()?.questions||[];
 const section=()=>state().section==='Reading and Writing'?'Reading and Writing':'Math';
 const byId=id=>questions().find(q=>q.id===id);
 const hardAllowed=()=>typeof canHard==='function'?!!canHard():!!canHard;
 const timingAllowed=()=>typeof canTimed==='function'?!!canTimed():!!canTimed;
 function currentRound(){
  const subject=section();if(subject!==previousSection){previousSection=subject;selectedId=null;setupSection=null;filters={...filters,skill:'all'};error='';}
  if(setupSection===subject)return null;
  const rows=studio().rushRounds.filter(r=>r.section===subject);
  return rows.find(r=>r.id===selectedId)||rows.find(r=>r.id===studio().activeRushId&&active(r))||rows.filter(active).at(-1)||rows.find(r=>r.id===studio().activeRushId)||null;
 }
 function persist(){save();}
 function show(){persist();rerender();}
 function choose(round){selectedId=round.id;setupSection=null;studio().activeRushId=round.id;}
 function matching(){const used=taken();return questions().filter(q=>q.section===section()&&!used.has(q.id)&&(filters.skill==='all'||q.skill===filters.skill)&&(filters.difficulty==='mixed'||q.difficulty===filters.difficulty)&&(hardAllowed()||q.difficulty!=='Hard'));}
 function heading(description){return `<header class="rush-heading"><div><a class="rush-back" href="#practice-hub">Practice</a><h1>Question Rush</h1><p>${esc(description)}</p></div><span class="rush-section">${esc(label(section()))}</span></header>`;}
 function history(){const rows=studio().rushRounds.filter(r=>r.section===section()&&!active(r)).slice(-6).reverse();if(!rows.length)return '';return `<section class="rush-history"><h2>Recent rounds</h2>${rows.map(r=>{const s=rushSummary(r);return `<button class="rush-history-row" data-action="rush-open" data-id="${esc(r.id)}"><span><strong>${s.correct} correct of ${s.seen??s.answered} seen</strong><small>${esc(r.skill&&r.skill!=='all'?r.skill:'Mixed skills')} · ${esc(r.pace)} pace${r.status==='ended'?' · ended early':''}</small></span><span>${elapsed(s.elapsedMs)}<span class="rush-history-view">View results</span></span></button>`;}).join('')}</section>`;}
 function setup(){
  const total=questions().filter(q=>q.section===section()).length,available=matching().length,unlocked=timingAllowed();
  const skills=[...new Set(questions().filter(q=>q.section===section()).map(q=>q.skill))].sort();
  const paceSeconds=(section()==='Math'?95:71)*({relaxed:1.5,standard:1,fast:.75}[filters.pace]||1.5);
  const suspended=studio().rushRounds.filter(r=>r.section===section()&&active(r)).at(-1);
  return `<div class="rush-page">${heading('A short round of fresh questions. Accuracy comes first; speed is a separate challenge.')}<div class="rush-setup-layout"><section class="rush-setup"><h2>Choose your round</h2><p class="rush-muted">${esc(label(section()))} is selected. Change sections in the app to practice the other subject.</p>${suspended?`<div class="rush-notice"><strong>You have a saved round.</strong><p>Its questions stay reserved until you finish or end it.</p><button class="secondary" data-action="rush-open" data-id="${esc(suspended.id)}">Resume question ${Math.min(suspended.index+1,suspended.count)} of ${suspended.count}</button></div>`:''}<form id="rush-create-form"><div class="rush-fields"><label for="rush-skill">Skill<select id="rush-skill" name="skill" data-rush-setting="skill"><option value="all">All available skills</option>${skills.map(s=>`<option value="${esc(s)}" ${filters.skill===s?'selected':''}>${esc(s)}</option>`).join('')}</select></label><label for="rush-difficulty">Difficulty<select id="rush-difficulty" name="difficulty" data-rush-setting="difficulty">${[['mixed','Mixed'],['Easy','Easy'],['Medium','Medium'],['Hard','Hard']].map(([value,title])=>`<option value="${value}" ${filters.difficulty===value?'selected':''} ${value==='Hard'&&!hardAllowed()?'disabled':''}>${title}${value==='Hard'&&!hardAllowed()?' · locked':''}</option>`).join('')}</select></label><label for="rush-count">Questions<select id="rush-count" name="count" data-rush-setting="count">${[5,10,20].map(n=>`<option value="${n}" ${filters.count===n?'selected':''}>${n} questions</option>`).join('')}</select></label><label for="rush-pace">Pace<select id="rush-pace" name="pace" data-rush-setting="pace">${[['relaxed','Relaxed'],['standard','Standard'],['fast','Fast']].map(([value,title])=>`<option value="${value}" ${filters.pace===value?'selected':''}>${title}</option>`).join('')}</select></label></div><div class="rush-plan"><div><strong>80%</strong><span>Accuracy target</span></div><div><strong>${clock(paceSeconds)}</strong><span>Per-question budget</span></div><div><strong>${available}</strong><span>Fresh matches</span></div></div><p class="rush-muted">Estimated question time: ${Math.ceil(paceSeconds*filters.count/60)} minutes, plus answer review.</p><p class="rush-muted">Relaxed gives extra time. Standard and Fast increase the pacing challenge. Each question has its own deadline, which continues if you leave the app.</p>${!total?'<div class="rush-notice"><h3>Bring your question bank first</h3><p>No official questions for this section are loaded. Import your supported question library to start a round. Original lessons remain available.</p><a class="secondary" href="setup.html">Import a question bank</a><a class="text-button" href="#lessons">Browse lessons</a></div>':available<filters.count?`<div class="rush-notice"><h3>${available?'More fresh questions needed':'No fresh questions match'}</h3><p>This round needs ${filters.count} unused questions. ${available?'Choose fewer questions, adjust the filters, or import more material.':'Change the filters or import more questions. Earlier questions stay available in Review.'}</p><a class="text-button" href="setup.html">Question-bank setup</a></div>`:''}${!unlocked?'<div class="rush-notice rush-lock"><h3>Build accuracy before adding a clock</h3><p>Question Rush unlocks after two stable sets of at least five questions with 80% correct, without help and with valid setups or reasoning. All Rush paces use a timer; untimed practice is available now.</p><a class="secondary" href="#practice">Continue untimed practice</a></div>':''}${!hardAllowed()?'<p class="rush-muted">Hard questions follow the app’s separate accuracy and setup readiness check. Mixed rounds currently use Easy and Medium questions.</p>':''}<p class="rush-error" id="rush-error" role="alert">${esc(error)}</p><button class="primary rush-start" type="submit" ${!unlocked||available<filters.count||suspended?'disabled':''}>Start ${filters.count}-question round</button></form></section><aside class="rush-how"><h2>One question at a time</h2><ol><li>Read, set up, and submit one answer.</li><li>Check the result and review the supplied explanation.</li><li>Start the next clock when you’re ready.</li></ol><p>Correct answers can earn up to three speed stars. Wrong answers, skips, and timeouts earn none. The accuracy result always stays visible.</p><p>Use Focused view to hide stars and streaks. Rush results are answer-only practice evidence, with no skill-mastery or SAT-score claim.</p>${history()}</aside></div></div>`;
 }
 function controls(q,answer){return /^[A-D]$/.test(q.answer)?`<fieldset class="rush-choices"><legend>Your answer</legend>${['A','B','C','D'].map(letter=>`<label><input type="radio" name="answer" value="${letter}" ${answer===letter?'checked':''} required><span>${letter}</span><span class="rush-choice-label">Choice ${letter}</span></label>`).join('')}</fieldset>`:`<label class="rush-numeric" for="rush-answer">Your answer<input id="rush-answer" name="answer" type="text" maxlength="100" value="${esc(answer)}" placeholder="Number, decimal, or fraction" autocomplete="off" required></label>`;}
 function questionContent(q){return questionHTML?questionHTML(q,{answer:'',disabled:false}):`<img class="bank-image" src="${safeURL(q.image)}" alt="${esc(q.section)} question ${esc(q.number)} on ${esc(q.skill)}, ID ${esc(q.id)}">`;}
 function explanation(q){const href=safeURL(q.key?.url||q.keyUrl);return `<p>Correct answer: <strong>${esc(q.answer)}</strong></p>${q.key?.rationale?`<details class="rush-rationale"><summary>Read the supplied explanation</summary><p>${esc(q.key.rationale)}</p></details>`:''}${href?`<a class="secondary" href="${href}" target="_blank" rel="noopener noreferrer">Official worked explanation</a>${q.key?.file?`<p class="rush-muted">${esc(q.key.file)} · page ${esc(q.key.page)} · ID ${esc(q.id)}</p>`:''} `:'<p class="rush-muted">No worked explanation is supplied for this question. Use its exact source above when reviewing the method.</p>'}${q.section==='Math'&&!renderTools?'<a class="text-button" href="#desmos">Review Desmos methods</a>':''}${renderTools?renderTools(q,{answered:true}):''}`;}
 function player(round){
  const q=byId(round.questionIds[round.index]);if(!q)return `<div class="rush-page">${heading('This saved round needs its question library.')}<section class="rush-setup"><p>The current question is missing from the loaded library. Import the same library to resume, or end this round.</p><a class="secondary" href="setup.html">Question-bank setup</a><button class="text-button" data-action="rush-end">End this round</button></section></div>`;
  const last=round.status==='feedback'?round.results.find(r=>r.questionId===q.id)||round.results.at(-1):null;
  const summary=rushSummary(round),seconds=rushRemaining(round),fraction=Math.max(0,Math.min(1,seconds/round.secondsPerQuestion));
  return `<div class="rush-page ${focused?'rush-focused':''}">${heading('Fresh questions, immediate feedback, and a moment to review before the next clock.')}<div class="rush-session-bar"><div><strong>Question ${round.index+1} of ${round.count}</strong><small>${esc(round.pace)} pace · target 80% correct</small></div><div class="rush-clock-wrap"><output id="rush-clock" class="rush-clock ${seconds<=15&&!last?'rush-clock-low':''}" aria-label="Time remaining for this question" aria-live="off">${last?'Stopped':clock(seconds)}</output><span class="rush-sr-only">The timer continues if you leave the app. It stops for answer feedback.</span><span id="rush-time-caption">${last?'Review at your pace':'Question time left'}</span></div><button class="secondary rush-view-toggle" data-action="rush-view" aria-pressed="${focused}">${focused?'Show Rush view':'Use Focused view'}</button></div><div class="rush-timeline" aria-label="Round progress">${round.questionIds.map((id,i)=>{const r=round.results.find(r=>r.questionId===id);return `<span class="${i===round.index?'current ':''}${r?r.correct?'correct':isTimedOut(r)?'timeout':r.skipped?'skipped':'incorrect':''}" aria-label="Question ${i+1}: ${r?outcome(r):i===round.index?'current':'not started'}"></span>`;}).join('')}</div><div class="rush-player-layout"><article class="rush-question"><header><div><h2>${esc(q.skill)}</h2><p>${esc(q.domain||q.section)}</p></div><span class="pill ${esc(String(q.difficulty).toLowerCase())}">${esc(q.difficulty)}</span></header><div class="rush-time-track" aria-hidden="true"><span id="rush-time-fill" style="width:${last?0:fraction*100}%"></span></div><div class="rush-question-content">${questionContent(q)}</div>${source(q)}${last?`<section class="rush-feedback ${last.correct?'is-correct':'is-review'}" role="status" tabindex="-1"><div class="rush-feedback-heading"><h3>${outcome(last)}</h3><span class="rush-game-only">${stars(last.stars)}</span></div><p>${last.answer?`Your answer: <strong>${esc(last.answer)}</strong>. `:''}${isTimedOut(last)?'The deadline passed before an answer was submitted.':last.skipped?'This question was skipped and earns no speed stars.':last.correct?'Your answer matches the supplied key.':'Use the explanation to check the step that needs work.'}</p>${explanation(q)}<p class="rush-muted">${last.correct?'Matching an answer does not verify your reasoning.':'This question stays in your Rush results for review.'} The original result is preserved.</p><button class="primary" data-action="rush-next">${round.index===round.questionIds.length-1?'See round results':'Start next question'}</button></section>`:`<form id="rush-answer-form">${controls(q,round.draftAnswer||'')}<p class="rush-error" id="rush-error" role="alert">${esc(error)}</p><div class="rush-answer-actions"><button class="primary" type="submit">Check answer</button><button class="text-button" type="button" data-action="rush-skip">Skip this question</button></div><p class="rush-muted">Submit with Enter. Feedback opens immediately, and your first answer is saved.</p></form>`}</article><aside class="rush-scoreboard"><h2>This round</h2><dl><div><dt>Correct</dt><dd>${summary.correct}<span> / ${summary.seen??summary.answered} seen</span></dd></div><div class="rush-game-only"><dt>Speed stars</dt><dd>${summary.stars}</dd></div><div class="rush-game-only"><dt>Current streak</dt><dd>${round.streak||0}</dd></div><div><dt>Accuracy target</dt><dd>80<span>%</span></dd></div></dl><p>${focused?'Focused view keeps the question, time, and accuracy visible.':'Stars reward correct answers within the question’s time budget. Accuracy is the main result.'}</p><details class="rush-end-confirm"><summary>End round early</summary><p>Save the questions already seen and leave the rest unused.</p><button class="secondary" data-action="rush-end">End and view results</button></details></aside></div></div>`;
 }
 function reviewUnanswered(round){return round.exposedIds.filter(id=>!round.results.some(r=>r.questionId===id)).map(id=>{const q=byId(id),index=round.questionIds.indexOf(id);return `<details class="rush-review-item"><summary><span><strong>${index+1}. ${esc(q?.skill||'Question')}</strong><small>Unanswered when the round ended</small></span></summary><p>No answer was submitted. This question was opened and stays out of fresh practice.</p>${q?questionContent(q)+explanation(q)+source(q):'<p class="rush-muted">Import the original library to view this question.</p>'}</details>`;}).join('');}
 function results(round){const s=rushSummary(round),unseen=Math.max(0,round.questionIds.length-round.exposedIds.length),accuracy=s.accuracy===null?'—':Math.round(s.accuracy*100)+'%';return `<div class="rush-page ${focused?'rush-focused':''}">${heading(round.status==='ended'?'Round ended. Your first results are saved.':'Round complete. Take a moment to review what happened.')}<section class="rush-result-lead"><div><p>${esc(label(round.section))} · ${esc(round.pace)} pace</p><h2>${s.correct} correct <span>of ${s.seen??s.answered} seen</span></h2><p>${s.answered&&s.accuracy>=.8?'You reached this round’s 80% accuracy target.':'Accuracy comes first. Review the misses before increasing the pace.'}</p></div><div class="rush-result-accuracy"><strong>${accuracy}</strong><span>Accuracy across seen questions</span></div></section><dl class="rush-result-stats"><div><dt>Incorrect</dt><dd>${s.incorrect}</dd></div><div><dt>Unanswered</dt><dd>${s.unanswered??s.timedOut+s.skipped}</dd></div><div><dt>Timed out</dt><dd>${s.timedOut}</dd></div><div><dt>Skipped</dt><dd>${s.skipped}</dd></div><div><dt>Question time</dt><dd>${elapsed(s.elapsedMs)}</dd></div><div class="rush-game-only"><dt>Speed stars</dt><dd>${s.stars}</dd></div><div class="rush-game-only"><dt>Best streak</dt><dd>${s.bestStreak}</dd></div></dl>${unseen?`<p class="rush-muted">${unseen} question${unseen===1?' was':'s were'} not opened and remain available for fresh practice.</p>`:''}<div class="rush-result-actions"><button class="primary" data-action="rush-new">Choose another round</button><a class="secondary" href="#review">Open Review</a><button class="text-button" data-action="rush-view" aria-pressed="${focused}">${focused?'Show speed details':'Hide speed details'}</button></div><section class="rush-skill-results"><h2>Results by exact skill</h2><div class="rush-table-wrap"><table><thead><tr><th scope="col">Skill</th><th scope="col">Correct</th><th scope="col">Incorrect</th><th scope="col">Unanswered</th><th scope="col">Accuracy</th></tr></thead><tbody>${s.skills.map(skill=>`<tr><th scope="row">${esc(skill.skill)}</th><td>${skill.correct} / ${skill.total}</td><td>${skill.incorrect}</td><td>${skill.unanswered??skill.timedOut+skill.skipped}</td><td>${Math.round(skill.accuracy*100)}%</td></tr>`).join('')||'<tr><td colspan="5">No questions were completed in this round.</td></tr>'}</tbody></table></div><p class="rush-muted">Answer-only practice, separate from setup mastery and SAT score estimates. Timeouts, skips, and questions left open when the round ended count as unanswered and earn no stars.</p></section><section class="rush-review"><h2>Review this round</h2>${s.results.map((r,i)=>{const q=byId(r.questionId);return `<details class="rush-review-item"><summary><span><strong>${i+1}. ${esc(r.skill||q?.skill||'Question')}</strong><small>${outcome(r)} · ${elapsed(r.elapsedMs)}</small></span><span class="rush-game-only">${stars(r.stars)}</span></summary>${q?`${questionContent(q)}<p>Your answer: <strong>${esc(r.answer||'Unanswered')}</strong></p>${explanation(q)}${source(q)}`:'<p class="rush-muted">Import this question’s original library to view its content. The saved result is retained.</p>'+source({file:r.source?.file,page:r.source?.page,number:r.source?.question,id:r.questionId})}</details>`;}).join('')}${reviewUnanswered(round)}</section></div>`;}
 function render(){const round=currentRound();if(round?.status==='active'&&expireRush(round)){persist();}return round?(active(round)?player(round):results(round)):setup();}
 function start(form){
  if(!timingAllowed())throw Error('Finish two stable untimed sets before starting timed Rush.');
  if(studio().rushRounds.some(r=>r.section===section()&&active(r)))throw Error('Resume or end the saved round in this section first.');
  const fields=new FormData(form);filters={skill:String(fields.get('skill')||'all'),difficulty:String(fields.get('difficulty')||'mixed'),count:Number(fields.get('count')),pace:String(fields.get('pace'))};
  if(filters.difficulty==='Hard'&&!hardAllowed())throw Error('Hard questions are not unlocked yet.');
  const round=createRush(questions(),taken(),{section:section(),...filters,allowHard:hardAllowed()});studio().rushRounds.push(round);choose(round);error='';show();
 }
 function submit(event){const form=event.target;if(!['rush-create-form','rush-answer-form'].includes(form.id))return false;event.preventDefault();try{if(form.id==='rush-create-form')start(form);else{const round=currentRound();if(!round||round.status!=='active')return true;const q=byId(round.questionIds[round.index]),answer=String(new FormData(form).get('answer')||'').trim();if(!answer)throw Error('Choose or enter an answer first.');if(!q)throw Error('Restore the question library before answering.');submitRushAnswer(round,q,answer,grade);delete round.draftAnswer;error='';show();document.querySelector('.rush-feedback')?.focus();}}catch(e){error=e.message;const box=document.getElementById('rush-error');if(box)box.textContent=error;}return true;}
 function click(action,target){if(!action?.startsWith('rush-'))return false;const round=currentRound();try{if(action==='rush-open'){const chosen=studio().rushRounds.find(r=>r.id===target.dataset.id&&r.section===section());if(chosen){choose(chosen);error='';show();}}else if(action==='rush-new'){selectedId=null;setupSection=section();error='';rerender();}else if(action==='rush-view'){focused=!focused;rerender();}else if(action==='rush-next'&&round?.status==='feedback'){advanceRush(round);delete round.draftAnswer;error='';show();}else if(action==='rush-skip'&&round?.status==='active'){const q=byId(round.questionIds[round.index]);if(!q)throw Error('Restore the question library before skipping.');skipRush(round,q);delete round.draftAnswer;error='';show();document.querySelector('.rush-feedback')?.focus();}else if(action==='rush-end'&&active(round)){endRush(round);delete round.draftAnswer;error='';show();}else return false;}catch(e){error=e.message;rerender();}return true;}
 function input(event){const target=event.target,setting=target.dataset?.rushSetting;if(setting){if(setting==='count')filters.count=Number(target.value);else if(['skill','difficulty','pace'].includes(setting))filters[setting]=target.value;else return false;error='';rerender();document.getElementById(target.id)?.focus();return true;}if(target.closest?.('#rush-answer-form')&&target.name==='answer'){const round=currentRound();if(round?.status==='active'){round.draftAnswer=String(target.value).slice(0,100);persist();}return true;}return false;}
 function tick(){if(typeof location!=='undefined'&&location.hash!=='#rush')return false;const round=currentRound();if(!round||round.status!=='active')return false;if(expireRush(round)){delete round.draftAnswer;show();return true;}const remaining=rushRemaining(round),el=document.getElementById('rush-clock'),fill=document.getElementById('rush-time-fill');if(el){el.textContent=clock(remaining);el.classList.toggle('rush-clock-low',remaining<=15);}if(fill)fill.style.width=Math.max(0,Math.min(100,remaining/round.secondsPerQuestion*100))+'%';return false;}
 return {render,click,submit,input,tick};
}
